use crate::project::compilation_database::CompilationDatabaseError;
use crate::project::{
    CompilationDatabase, ProjectComponent, ProjectComponentProvider, ProjectError,
};
use std::collections::HashMap;
use std::path::{Path, PathBuf};

/// Fallback provider for compilation databases generated by any build system or IDE.
#[derive(Default)]
pub struct CompilationDatabaseProvider;

impl CompilationDatabaseProvider {
    pub fn new() -> Self {
        Self
    }

    fn database_error(error: CompilationDatabaseError) -> ProjectError {
        match error {
            CompilationDatabaseError::FileNotFound { path } => {
                ProjectError::CompilationDatabaseNotFound { path }
            }
            CompilationDatabaseError::ReadError { error } => {
                ProjectError::CompilationDatabaseNotReadable { error }
            }
            CompilationDatabaseError::ParseError { error } => {
                ProjectError::CompilationDatabaseInvalid { error }
            }
            CompilationDatabaseError::EmptyDatabase => ProjectError::CompilationDatabaseEmpty,
        }
    }

    fn source_root(
        database: &CompilationDatabase,
        workspace_root: Option<&Path>,
        build_dir: &Path,
    ) -> Result<PathBuf, ProjectError> {
        if let Some(workspace_root) = workspace_root {
            let workspace_root = workspace_root
                .canonicalize()
                .unwrap_or_else(|_| workspace_root.to_path_buf());
            return Ok(workspace_root);
        }

        let source_files = database
            .canonical_source_files()
            .map_err(Self::database_error)?;
        // Without build-system metadata, only the common source directory can be inferred.
        let mut common_parent = source_files
            .first()
            .and_then(|file| file.parent())
            .map(Path::to_path_buf)
            .unwrap_or_else(|| build_dir.to_path_buf());
        for file in &source_files {
            while !file.starts_with(&common_parent) {
                if !common_parent.pop() {
                    return Ok(build_dir.to_path_buf());
                }
            }
        }
        while !common_parent.is_dir() {
            if !common_parent.pop() {
                return Ok(build_dir.to_path_buf());
            }
        }
        Ok(common_parent)
    }
}

impl ProjectComponentProvider for CompilationDatabaseProvider {
    fn scan_path(&self, path: &Path) -> Result<Option<ProjectComponent>, ProjectError> {
        self.scan_path_with_source_root(path, None)
    }

    fn scan_path_with_source_root(
        &self,
        path: &Path,
        source_root: Option<&Path>,
    ) -> Result<Option<ProjectComponent>, ProjectError> {
        let database_path = path.join("compile_commands.json");
        if !database_path.exists() {
            return Ok(None);
        }
        let database =
            CompilationDatabase::new(database_path.clone()).map_err(Self::database_error)?;
        let source_root = Self::source_root(&database, source_root, path)?;
        ProjectComponent::new(
            path.to_path_buf(),
            source_root,
            database_path,
            "compilation_database".to_string(),
            "Unknown".to_string(),
            "Unknown".to_string(),
            HashMap::new(),
        )
        .map(Some)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::project::ProjectScanner;
    use crate::project::scanner::ScanOptions;
    use std::fs;
    use tempfile::TempDir;

    fn write_database(build_dir: &Path, source_file: &Path) {
        fs::create_dir_all(build_dir).unwrap();
        fs::create_dir_all(source_file.parent().unwrap()).unwrap();
        fs::write(source_file, "int main() {}\n").unwrap();
        fs::write(
            build_dir.join("compile_commands.json"),
            serde_json::to_vec(&serde_json::json!([{
                "directory": source_file.parent().unwrap(),
                "file": source_file,
                "arguments": ["c++", "-c", source_file]
            }]))
            .unwrap(),
        )
        .unwrap();
    }

    #[test]
    fn ignores_directories_without_database() {
        let temp = TempDir::new().unwrap();
        assert!(
            CompilationDatabaseProvider::new()
                .scan_path(temp.path())
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn validates_database_before_accepting_component() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("compile_commands.json");
        for content in ["not json", "{}", "[{}]"] {
            fs::write(&path, content).unwrap();
            assert!(matches!(
                CompilationDatabaseProvider::new().scan_path(temp.path()),
                Err(ProjectError::CompilationDatabaseInvalid { .. })
            ));
        }
        fs::write(path, "[]").unwrap();
        assert!(matches!(
            CompilationDatabaseProvider::new().scan_path(temp.path()),
            Err(ProjectError::CompilationDatabaseEmpty)
        ));
    }

    #[test]
    fn discovers_root_and_nested_databases_without_build_metadata() {
        let temp = TempDir::new().unwrap();
        let root = temp.path();
        write_database(root, &root.join("src/main.cpp"));
        write_database(&root.join("build/debug"), &root.join("lib/helper.cpp"));
        let workspace = ProjectScanner::default()
            .scan_project(root, 1, None)
            .unwrap();
        assert_eq!(workspace.components.len(), 2);
        for component in workspace.components {
            assert_eq!(component.provider_type, "compilation_database");
            assert_eq!(component.source_root_path, root.canonicalize().unwrap());
            assert_eq!(component.generator, "Unknown");
            assert_eq!(component.build_type, "Unknown");
            assert!(component.build_options.is_empty());
        }
    }

    #[test]
    fn discovers_explicit_hidden_and_external_database_directories() {
        let temp = TempDir::new().unwrap();
        let source_root = temp.path().join("project");
        let build_dir = temp.path().join("elsewhere/.qtc_clangd");
        write_database(&build_dir, &source_root.join("src/main.cpp"));
        let scanner = ProjectScanner::default();
        let component = scanner
            .discover_component_with_source_root(&build_dir, Some(&source_root))
            .unwrap()
            .unwrap();
        assert_eq!(component.build_dir_path, build_dir);
        assert_eq!(
            component.source_root_path,
            source_root.canonicalize().unwrap()
        );
        let inferred = scanner.discover_component(&build_dir).unwrap().unwrap();
        assert_eq!(
            inferred.source_root_path,
            source_root.join("src").canonicalize().unwrap()
        );
    }

    #[test]
    fn preserves_explicit_workspace_root_for_external_only_entries() {
        let temp = TempDir::new().unwrap();
        let workspace_root = temp.path().join("workspace");
        fs::create_dir(&workspace_root).unwrap();
        let build_dir = temp.path().join("build");
        write_database(&build_dir, &temp.path().join("external/main.cpp"));
        let component = ProjectScanner::default()
            .discover_component_with_source_root(&build_dir, Some(&workspace_root))
            .unwrap()
            .unwrap();
        assert_eq!(
            component.source_root_path,
            workspace_root.canonicalize().unwrap()
        );
    }

    #[test]
    fn infers_common_source_root_when_database_is_outside_sources() {
        let temp = TempDir::new().unwrap();
        let source_root = temp.path().join("project");
        let build_dir = temp.path().join("build");
        write_database(&build_dir, &source_root.join("src/main.cpp"));
        let mut entries: serde_json::Value =
            serde_json::from_slice(&fs::read(build_dir.join("compile_commands.json")).unwrap())
                .unwrap();
        let helper = source_root.join("lib/helper.cpp");
        fs::create_dir_all(helper.parent().unwrap()).unwrap();
        fs::write(&helper, "int helper();").unwrap();
        entries.as_array_mut().unwrap().push(serde_json::json!({
            "directory": &source_root,
            "file": &helper,
            "arguments": ["c++", "-c", &helper]
        }));
        fs::write(
            build_dir.join("compile_commands.json"),
            serde_json::to_vec(&entries).unwrap(),
        )
        .unwrap();
        let component = ProjectScanner::default()
            .discover_component(&build_dir)
            .unwrap()
            .unwrap();
        assert_eq!(
            component.source_root_path,
            source_root.canonicalize().unwrap()
        );
    }

    #[test]
    fn discovers_qt_creator_database_but_prunes_other_hidden_subtrees() {
        let temp = TempDir::new().unwrap();
        let root = temp.path();
        write_database(&root.join(".qtc_clangd"), &root.join("main.cpp"));
        write_database(&root.join(".cache/visible-build"), &root.join("main.cpp"));
        write_database(&root.join(".git/.qtc_clangd"), &root.join("main.cpp"));
        let scanner = ProjectScanner::default();
        let workspace = scanner.scan_project(root, 2, None).unwrap();
        assert_eq!(workspace.components.len(), 1);
        assert_eq!(
            workspace.components[0].build_dir_path,
            root.join(".qtc_clangd")
        );
        let workspace = scanner
            .scan_project(
                root,
                2,
                Some(ScanOptions {
                    skip_hidden: false,
                    ..ScanOptions::default()
                }),
            )
            .unwrap();
        assert_eq!(workspace.components.len(), 3);
        let explicit = scanner
            .scan_project(&root.join(".cache/visible-build"), 0, None)
            .unwrap();
        assert_eq!(explicit.components.len(), 1);
    }

    #[cfg(unix)]
    #[test]
    fn skips_hidden_directory_symlinks_unless_explicitly_selected() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().join("workspace");
        let build_dir = temp.path().join("external-build");
        write_database(&build_dir, &root.join("main.cpp"));
        let hidden_link = root.join(".hidden-build");
        std::os::unix::fs::symlink(&build_dir, &hidden_link).unwrap();
        let scanner = ProjectScanner::default();
        for follow_symlinks in [false, true] {
            let workspace = scanner
                .scan_project(
                    &root,
                    1,
                    Some(ScanOptions {
                        follow_symlinks,
                        ..ScanOptions::default()
                    }),
                )
                .unwrap();
            assert!(workspace.components.is_empty());
        }
        let component = scanner.discover_component(&hidden_link).unwrap().unwrap();
        assert_eq!(component.build_dir_path, hidden_link);
        let workspace = scanner.scan_project(&hidden_link, 0, None).unwrap();
        assert_eq!(workspace.components.len(), 1);
    }

    #[test]
    fn malformed_database_does_not_prevent_other_discoveries() {
        let temp = TempDir::new().unwrap();
        fs::write(temp.path().join("compile_commands.json"), "[]").unwrap();
        write_database(&temp.path().join("build"), &temp.path().join("main.cpp"));
        let workspace = ProjectScanner::default()
            .scan_project(temp.path(), 1, None)
            .unwrap();
        assert_eq!(workspace.components.len(), 1);
    }

    #[test]
    fn preserves_cmake_and_meson_provider_precedence() {
        let temp = TempDir::new().unwrap();
        let root = temp.path();
        let cmake = root.join("cmake-build");
        let meson = root.join("meson-build");
        for build in [&cmake, &meson] {
            write_database(build, &root.join("main.cpp"));
        }
        fs::write(
            cmake.join("CMakeCache.txt"),
            format!(
                "CMAKE_SOURCE_DIR:STATIC={}\nCMAKE_GENERATOR:INTERNAL=Ninja\n",
                root.display()
            ),
        )
        .unwrap();
        fs::create_dir(meson.join("meson-info")).unwrap();
        fs::write(
            meson.join("meson-info/intro-projectinfo.json"),
            serde_json::to_vec(&serde_json::json!({"source_dir": root})).unwrap(),
        )
        .unwrap();
        let scanner = ProjectScanner::default();
        assert_eq!(
            scanner
                .discover_component(&cmake)
                .unwrap()
                .unwrap()
                .provider_type,
            "cmake"
        );
        assert_eq!(
            scanner
                .discover_component(&meson)
                .unwrap()
                .unwrap()
                .provider_type,
            "meson"
        );
        fs::remove_file(cmake.join("compile_commands.json")).unwrap();
        assert!(matches!(
            scanner.discover_component(&cmake),
            Err(ProjectError::CompilationDatabaseNotFound { .. })
        ));
    }
}
